def shortest_path(graph, source, target):
    # Create a dictionary to track the distance from the source to each node
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    # Create a dictionary to track the previous node in the path
    previous_nodes = {node: None for node in graph}
    # Create a set of nodes that have been processed
    processed_nodes = set()

    while processed_nodes != set(graph):
        # Get the unprocessed node with the smallest distance
        current_node = min([node for node in graph if node not in processed_nodes], key=lambda x: distances[x])
        if distances[current_node] == float("inf"):
            return float("inf"), None
        processed_nodes.add(current_node)

        # Check all neighbors of the current node
        for neighbor, weight in graph[current_node]:
            # Calculate the new distance to the neighbor
            distance_through_current = distances[current_node] + weight
            if distance_through_current < distances[neighbor]:
                distances[neighbor] = distance_through_current
                previous_nodes[neighbor] = current_node

    # Reconstruct the path from the source to the target
    path = []
    node = target
    while node is not None:
        path.insert(0, node)
        node = previous_nodes[node]
    if path[-1] == source:
        return distances[target], path
    else:
        return float("inf"), None
