def shortest_path(graph, source, target):
    if source == target:
        return (0, [source])

    # Initialize distances to unknown
    unknown = {node: float('inf') for node in graph}
    # Unknown parents are None
    unknown_parents = {node: None for node in graph}
    # The distance to the starting node is 0
    unknown[source] = 0
    # The current node is the starting node
    current = source

    # Until we reach the target or there are no unknown nodes left
    while current is not None:
        # If we found the target, return the path
        if current == target:
            path = []
            while current is not None:
                path.append(current)
                current = unknown_parents[current]
            path.reverse()
            return (unknown[target], path)
        # Mark the current node as visited
        visited = True
        for neighbour, weight in graph[current]:
            if unknown[neighbour] > unknown[current] + weight:
                unknown[neighbour] = unknown[current] + weight
                unknown_parents[neighbour] = current
            visited = False
        # Move to the next unknown node
        for node in unknown:
            if visited or unknown[node] < unknown[current]:
                current = node

    # If we can't reach the target, return infinity and None
    return (float('inf'), None)
