def shortest_path(graph, source, target):
    # Initialize distances to infinity
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    # Initialize previous nodes
    previous = {node: None for node in graph}
    # Set of all visited nodes
    visited = set()

    def relax(u, v, weight):
        if distances[u] + weight < distances[v]:
            distances[v] = distances[u] + weight
            previous[v] = u

    while target not in visited:
        # Find unvisited nodes with shortest known distance
        current = min((node for node in graph if node not in visited), key=lambda node: distances[node])
        visited.add(current)

        # Relax all edges connected to the current node
        for neighbor, weight in graph[current]:
            relax(current, neighbor, weight)

    # If the target node is not reachable, distances[target] is still infinity
    if distances[target] == float("inf"):
        return float("inf"), None
    else:
        # Reconstruct the path
        path = []
        current = target
        while current is not None:
            path.append(current)
            current = previous[current]
        return distances[target], path[::-1]
