def shortest_path(graph, source, target):
    # Floyd-Warshall algorithm to find the shortest paths in a weighted graph
    num_nodes = len(graph)
    distances = [[float("inf") for _ in range(num_nodes)] for _ in range(num_nodes)]
    paths = [[None for _ in range(num_nodes)] for _ in range(num_nodes)]

    # Initialize the distances matrix
    for i in range(num_nodes):
        for j, weight in graph[i]:
            distances[i][j] = weight
            paths[i][j] = [i, j]

    # Floyd-Warshall algorithm
    for k in range(num_nodes):
        for i in range(num_nodes):
            for j in range(num_nodes):
                if distances[i][k] + distances[k][j] < distances[i][j]:
                    distances[i][j] = distances[i][k] + distances[k][j]
                    paths[i][j] = paths[i][k] + [j]

    # Check if the target is reachable from the source
    if distances[source][target] == float("inf"):
        return float("inf"), None
    else:
        return distances[source][target], paths[source][target]

