def shortest_path(graph, source, target):
    # Track visited nodes and their parents for backtracking
    visited = {source: None}
    # Initialize distances, set source distance to 0, others to infinity
    distances = {node: float("inf") for node in graph}
    distances[source] = 0

    # Queue for BFS, contains a tuple (current node, current distance)
    queue = deque([(source, 0)])

    while queue:
        current_node, current_distance = queue.popleft()

        # If the current node is the target, reconstruct the path
        if current_node == target:
            path = [target]
            while current_node is not None:
                path.append(current_node)
                current_node = visited[current_node]
            path.reverse()
            return (current_distance, path)

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            if neighbor not in visited:
                visited[neighbor] = current_node
                distances[neighbor] = current_distance + weight
                queue.append((neighbor, current_distance + weight))

    # If we exit the loop without finding the target, the target is unreachable
    return (float("inf"), None)

