def shortest_path(graph, source, target):
    # Initialize distances to unreachable (infinity) and previous nodes to None
    distances = {node: float('inf') for node in graph}
    previous = {node: None for node in graph}
    distances[source] = 0
    current = source

    # Start the BFS
    while current is not None:
        for neighbour, weight in graph[current]:
            new_distance = distances[current] + weight
            if new_distance < distances[neighbour]:
                distances[neighbour] = new_distance
                previous[neighbour] = current
        unvisited_neighbours = [node for node in graph if node is not current and node not in distances]
        if not unvisited_neighbours:
            break
        current = min(unvisited_neighbours, key=lambda node: distances[node])

    # If target is still unreachable, return infinity and None
    if distances[target] == float('inf'):
        return float('inf'), None

    # Reconstruct the shortest path from target to source
    path = []
    while target is not None:
        path.append(target)
        target = previous[target]
    path.reverse()
    return distances[target], path
